module fir_tap_srl_dsp_tb;
    reg clk;
    reg rst;
    reg shift_en;
    reg accum_en;
    reg [7:0] sample_in;
    reg [7:0] coeff;
    wire [19:0] acc;
    integer errors = 0;
    integer i, j;
    reg [7:0] ref_delay [0:31];
    reg [19:0] expected_acc;
    reg [7:0] test_samples [0:39];
    reg [7:0] delayed_sample;

    fir_tap_srl_dsp uut (
        .clk(clk),
        .rst(rst),
        .shift_en(shift_en),
        .accum_en(accum_en),
        .sample_in(sample_in),
        .coeff(coeff),
        .acc(acc)
    );

    initial clk = 0;
    always #5 clk = ~clk;

    initial begin
        $display("==========Testbench results==========");
        $display("=====================================");

        #100; // Wait for Vivado's global GSR reset pulse (glbl.v, ~100ns) to release before driving
              // stimulus, otherwise structurally-instantiated UNISIM primitives (e.g. DSP48E1) hold
              // their registers forced to 0.

        for (i = 0; i < 40; i = i + 1)
            test_samples[i] = (i * 5 + 11) & 8'hFF;
        for (i = 0; i < 32; i = i + 1)
            ref_delay[i] = 8'h00;

        rst = 1; shift_en = 0; accum_en = 0; sample_in = 0; coeff = 8'd3;
        expected_acc = 0;
        @(posedge clk); #1;
        rst = 0;

        for (i = 0; i < 32; i = i + 1) begin
            sample_in = test_samples[i];
            shift_en = 1;
            @(posedge clk); #1;
            for (j = 31; j > 0; j = j - 1)
                ref_delay[j] = ref_delay[j - 1];
            ref_delay[0] = sample_in;
        end

        accum_en = 1;
        for (i = 32; i < 40; i = i + 1) begin
            sample_in = test_samples[i];
            delayed_sample = ref_delay[31];
            shift_en = 1;
            @(posedge clk); #1;
            expected_acc = expected_acc + (delayed_sample * coeff);
            for (j = 31; j > 0; j = j - 1)
                ref_delay[j] = ref_delay[j - 1];
            ref_delay[0] = sample_in;

            if (acc === expected_acc)
                $display(" cycle %0d delayed_sample=%0d coeff=%0d | acc=%0d (expected %0d) | PASS", i, delayed_sample, coeff, acc, expected_acc);
            else begin
                $display(" cycle %0d delayed_sample=%0d coeff=%0d | acc=%0d (expected %0d) | FAIL", i, delayed_sample, coeff, acc, expected_acc);
                errors = errors + 1;
            end
        end

        accum_en = 0;
        sample_in = 8'd200;
        shift_en = 0;
        @(posedge clk); #1;
        if (acc === expected_acc)
            $display(" hold | acc=%0d (expected %0d) | PASS", acc, expected_acc);
        else begin
            $display(" hold | acc=%0d (expected %0d) | FAIL", acc, expected_acc);
            errors = errors + 1;
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
